import { useState } from "react";
import { motion } from "framer-motion";
import {
  Briefcase,
  GraduationCap,
  Plus,
  Sparkles,
  Trash2,
  X,
} from "lucide-react";
import { useStore } from "@/store/useStore";
import { PageHeader } from "@/components/PageHeader";
import { ResumeDocument } from "@/components/ResumeDocument";
import { cn } from "@/lib/utils";

export default function ProfilePage() {
  const master = useStore((s) => s.master);
  const rules = useStore((s) => s.settings.rules);
  const updateMaster = useStore((s) => s.updateMaster);
  const addExperience = useStore((s) => s.addExperience);
  const updateExperience = useStore((s) => s.updateExperience);
  const removeExperience = useStore((s) => s.removeExperience);
  const addBullet = useStore((s) => s.addBullet);
  const updateBullet = useStore((s) => s.updateBullet);
  const removeBullet = useStore((s) => s.removeBullet);
  const addEducation = useStore((s) => s.addEducation);
  const updateEducation = useStore((s) => s.updateEducation);
  const removeEducation = useStore((s) => s.removeEducation);
  const [skillDraft, setSkillDraft] = useState("");

  const addSkill = () => {
    const next = skillDraft.trim();
    if (!next) return;
    if (master.skills.includes(next)) {
      setSkillDraft("");
      return;
    }
    updateMaster({ skills: [...master.skills, next] });
    setSkillDraft("");
  };

  const removeSkill = (skill: string) =>
    updateMaster({ skills: master.skills.filter((s) => s !== skill) });

  return (
    <div className="px-8 py-10 max-w-[1400px] mx-auto">
      <PageHeader
        eyebrow="Master Profile"
        title="Your source of truth"
        description="Capture every role, every bullet, every skill once. We'll tailor it to each job for you — no fabrication, no rewrites that change meaning."
      />

      <div className="grid grid-cols-1 xl:grid-cols-[minmax(0,1fr)_auto] gap-10">
        <div className="space-y-8">
          <Section
            icon={<Sparkles className="h-4 w-4 text-indigo-500" />}
            title="Identity"
            subtitle="Header that appears on every resume."
          >
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              <Field label="Full Name">
                <input
                  className="field"
                  value={master.contact.fullName}
                  onChange={(e) =>
                    updateMaster({
                      contact: { ...master.contact, fullName: e.target.value },
                    })
                  }
                  placeholder="Alex Morgan"
                />
              </Field>
              <Field label="Headline">
                <input
                  className="field"
                  value={master.contact.headline}
                  onChange={(e) =>
                    updateMaster({
                      contact: { ...master.contact, headline: e.target.value },
                    })
                  }
                  placeholder="Senior Product Designer"
                />
              </Field>
              <Field label="Email">
                <input
                  className="field"
                  type="email"
                  value={master.contact.email}
                  onChange={(e) =>
                    updateMaster({
                      contact: { ...master.contact, email: e.target.value },
                    })
                  }
                  placeholder="alex@example.com"
                />
              </Field>
              <Field label="Phone">
                <input
                  className="field"
                  value={master.contact.phone}
                  onChange={(e) =>
                    updateMaster({
                      contact: { ...master.contact, phone: e.target.value },
                    })
                  }
                  placeholder="+1 555 123 4567"
                />
              </Field>
              <Field label="Location">
                <input
                  className="field"
                  value={master.contact.location}
                  onChange={(e) =>
                    updateMaster({
                      contact: { ...master.contact, location: e.target.value },
                    })
                  }
                  placeholder="Brooklyn, NY"
                />
              </Field>
              <Field label="Link Label">
                <input
                  className="field"
                  value={master.contact.linkLabel}
                  onChange={(e) =>
                    updateMaster({
                      contact: { ...master.contact, linkLabel: e.target.value },
                    })
                  }
                  placeholder="alex.design"
                />
              </Field>
              <Field label="Link URL" className="md:col-span-2">
                <input
                  className="field"
                  value={master.contact.linkUrl}
                  onChange={(e) =>
                    updateMaster({
                      contact: { ...master.contact, linkUrl: e.target.value },
                    })
                  }
                  placeholder="https://alex.design"
                />
              </Field>
            </div>
          </Section>

          <Section
            title="Summary"
            subtitle="Two or three sentences. We'll tighten it for each role."
          >
            <textarea
              className="field-textarea min-h-[110px]"
              value={master.summary}
              onChange={(e) => updateMaster({ summary: e.target.value })}
              placeholder="Product designer with 8 years shipping consumer software at the intersection of design systems and AI tooling…"
            />
          </Section>

          <Section
            icon={<Briefcase className="h-4 w-4 text-indigo-500" />}
            title="Experience"
            subtitle={`Up to ${rules.maxBulletsPerRole} bullets per role will appear on the tailored resume — but capture them all here.`}
            action={
              <button onClick={addExperience} className="btn-secondary">
                <Plus className="h-4 w-4" />
                Add role
              </button>
            }
          >
            {master.experiences.length === 0 ? (
              <EmptyState
                title="No experience yet"
                cta="Add your first role"
                onClick={addExperience}
              />
            ) : (
              <div className="space-y-4">
                {master.experiences.map((exp, idx) => (
                  <motion.div
                    key={exp.id}
                    initial={{ opacity: 0, y: 4 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.2, delay: idx * 0.02 }}
                    className="surface p-5"
                  >
                    <div className="flex items-start justify-between gap-2 mb-4">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-3 flex-1">
                        <input
                          className="field"
                          placeholder="Company"
                          value={exp.company}
                          onChange={(e) =>
                            updateExperience(exp.id, {
                              company: e.target.value,
                            })
                          }
                        />
                        <input
                          className="field"
                          placeholder="Role"
                          value={exp.role}
                          onChange={(e) =>
                            updateExperience(exp.id, { role: e.target.value })
                          }
                        />
                        <input
                          className="field"
                          placeholder="Location (optional)"
                          value={exp.location}
                          onChange={(e) =>
                            updateExperience(exp.id, {
                              location: e.target.value,
                            })
                          }
                        />
                        <div className="flex gap-2">
                          <input
                            className="field"
                            type="month"
                            value={exp.startDate}
                            onChange={(e) =>
                              updateExperience(exp.id, {
                                startDate: e.target.value,
                              })
                            }
                          />
                          <input
                            className="field"
                            type="month"
                            value={exp.endDate}
                            placeholder="Present"
                            onChange={(e) =>
                              updateExperience(exp.id, {
                                endDate: e.target.value,
                              })
                            }
                          />
                        </div>
                      </div>
                      <button
                        onClick={() => removeExperience(exp.id)}
                        className="btn-danger px-2 h-9"
                        title="Delete role"
                      >
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </div>

                    <div className="space-y-2">
                      {exp.bullets.map((b) => (
                        <BulletEditor
                          key={b.id}
                          text={b.text}
                          maxChars={rules.maxBulletChars}
                          onChange={(text) =>
                            updateBullet(exp.id, b.id, text)
                          }
                          onRemove={() => removeBullet(exp.id, b.id)}
                        />
                      ))}
                      <button
                        onClick={() => addBullet(exp.id)}
                        className="btn-ghost text-indigo-600 hover:bg-indigo-50 hover:text-indigo-700 h-9 text-sm"
                      >
                        <Plus className="h-4 w-4" /> Add bullet
                      </button>
                    </div>
                  </motion.div>
                ))}
              </div>
            )}
          </Section>

          <Section
            title="Skills"
            subtitle={`We'll keep the most relevant ${rules.maxSkills} on each tailored resume.`}
          >
            <div className="flex gap-2 mb-3">
              <input
                className="field"
                value={skillDraft}
                onChange={(e) => setSkillDraft(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    e.preventDefault();
                    addSkill();
                  }
                }}
                placeholder="Type a skill and press Enter"
              />
              <button onClick={addSkill} className="btn-secondary">
                <Plus className="h-4 w-4" />
                Add
              </button>
            </div>
            {master.skills.length === 0 ? (
              <p className="text-sm text-slate-500">No skills added yet.</p>
            ) : (
              <div className="flex flex-wrap gap-2">
                {master.skills.map((s) => (
                  <button
                    key={s}
                    onClick={() => removeSkill(s)}
                    className="group inline-flex items-center gap-1.5 rounded-full bg-slate-100 hover:bg-rose-50 hover:text-rose-700 px-3 py-1 text-sm font-medium text-slate-700 transition-colors"
                  >
                    {s}
                    <X className="h-3 w-3 opacity-50 group-hover:opacity-100" />
                  </button>
                ))}
              </div>
            )}
          </Section>

          <Section
            icon={<GraduationCap className="h-4 w-4 text-indigo-500" />}
            title="Education"
            action={
              <button onClick={addEducation} className="btn-secondary">
                <Plus className="h-4 w-4" />
                Add
              </button>
            }
          >
            {master.education.length === 0 ? (
              <EmptyState
                title="No education yet"
                cta="Add education"
                onClick={addEducation}
              />
            ) : (
              <div className="space-y-3">
                {master.education.map((ed) => (
                  <div key={ed.id} className="surface p-4">
                    <div className="flex items-start justify-between gap-2">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-3 flex-1">
                        <input
                          className="field"
                          placeholder="School"
                          value={ed.school}
                          onChange={(e) =>
                            updateEducation(ed.id, { school: e.target.value })
                          }
                        />
                        <input
                          className="field"
                          placeholder="Degree"
                          value={ed.degree}
                          onChange={(e) =>
                            updateEducation(ed.id, { degree: e.target.value })
                          }
                        />
                        <div className="flex gap-2 md:col-span-2">
                          <input
                            className="field"
                            type="month"
                            value={ed.startDate}
                            onChange={(e) =>
                              updateEducation(ed.id, {
                                startDate: e.target.value,
                              })
                            }
                          />
                          <input
                            className="field"
                            type="month"
                            value={ed.endDate}
                            onChange={(e) =>
                              updateEducation(ed.id, {
                                endDate: e.target.value,
                              })
                            }
                          />
                        </div>
                        <input
                          className="field md:col-span-2"
                          placeholder="Detail (e.g., GPA, honors)"
                          value={ed.detail}
                          onChange={(e) =>
                            updateEducation(ed.id, { detail: e.target.value })
                          }
                        />
                      </div>
                      <button
                        onClick={() => removeEducation(ed.id)}
                        className="btn-danger px-2 h-9"
                      >
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </Section>
        </div>

        <div className="hidden xl:block sticky top-10 self-start">
          <p className="label mb-3">Live preview</p>
          <div className="origin-top-right scale-[0.62] -translate-x-2">
            <div className="surface overflow-hidden">
              <ResumeDocument master={master} rules={rules} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function Section({
  title,
  subtitle,
  icon,
  action,
  children,
}: {
  title: string;
  subtitle?: string;
  icon?: React.ReactNode;
  action?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <section>
      <div className="flex items-end justify-between gap-3 mb-3">
        <div>
          <h2 className="flex items-center gap-2 text-base font-semibold text-slate-900">
            {icon}
            {title}
          </h2>
          {subtitle && (
            <p className="text-sm text-slate-500 mt-0.5">{subtitle}</p>
          )}
        </div>
        {action}
      </div>
      {children}
    </section>
  );
}

function Field({
  label,
  children,
  className,
}: {
  label: string;
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <label className={cn("space-y-1.5 block", className)}>
      <span className="label">{label}</span>
      {children}
    </label>
  );
}

function BulletEditor({
  text,
  maxChars,
  onChange,
  onRemove,
}: {
  text: string;
  maxChars: number;
  onChange: (v: string) => void;
  onRemove: () => void;
}) {
  const over = text.length > maxChars;
  return (
    <div className="group flex items-start gap-2">
      <span className="mt-3 h-1.5 w-1.5 rounded-full bg-slate-300 shrink-0" />
      <div className="flex-1">
        <textarea
          className={cn(
            "field-textarea min-h-[44px] py-2",
            over && "border-amber-400 focus:ring-amber-300/40"
          )}
          rows={2}
          value={text}
          onChange={(e) => onChange(e.target.value)}
          placeholder="Action verb + what you did + measurable outcome…"
        />
        <div className="mt-1 flex items-center justify-between">
          <span
            className={cn(
              "text-[11px]",
              over ? "text-amber-600 font-medium" : "text-slate-400"
            )}
          >
            {text.length}/{maxChars}
            {over && " — too long, will be trimmed"}
          </span>
        </div>
      </div>
      <button
        onClick={onRemove}
        className="opacity-0 group-hover:opacity-100 transition-opacity btn-danger px-2 h-9"
        title="Delete bullet"
      >
        <X className="h-4 w-4" />
      </button>
    </div>
  );
}

function EmptyState({
  title,
  cta,
  onClick,
}: {
  title: string;
  cta: string;
  onClick: () => void;
}) {
  return (
    <div className="surface p-8 text-center">
      <p className="text-sm text-slate-500 mb-3">{title}</p>
      <button onClick={onClick} className="btn-primary">
        <Plus className="h-4 w-4" />
        {cta}
      </button>
    </div>
  );
}
