import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  Building2,
  Calendar,
  FileText,
  Pencil,
  Printer,
  Trash2,
  X,
} from "lucide-react";
import { useStore } from "@/store/useStore";
import { PageHeader } from "@/components/PageHeader";
import { ResumeDocument } from "@/components/ResumeDocument";
import { formatDateLong } from "@/lib/utils";
import type { TailoredResume } from "@/types";

export default function LibraryPage() {
  const library = useStore((s) => s.library);
  const master = useStore((s) => s.master);
  const rules = useStore((s) => s.settings.rules);
  const removeTailored = useStore((s) => s.removeTailored);
  const renameTailored = useStore((s) => s.renameTailored);

  const [openId, setOpenId] = useState<string | null>(null);
  const [renamingId, setRenamingId] = useState<string | null>(null);
  const [renameDraft, setRenameDraft] = useState("");

  const open = library.find((r) => r.id === openId) ?? null;

  return (
    <div className="px-8 py-10 max-w-[1400px] mx-auto">
      <PageHeader
        eyebrow="Library"
        title="Every tailored version, saved"
        description="Your past tailoring runs. Reopen, reprint, or compare."
      />

      {library.length === 0 ? (
        <div className="surface p-12 text-center">
          <FileText className="h-10 w-10 mx-auto text-slate-300 mb-3" />
          <h3 className="text-base font-semibold text-slate-900">
            No saved resumes yet
          </h3>
          <p className="text-sm text-slate-500 mt-1">
            Run a tailoring on the Tailor page and click "Save to library."
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {library.map((r) => (
            <motion.button
              key={r.id}
              onClick={() => setOpenId(r.id)}
              initial={{ opacity: 0, y: 4 }}
              animate={{ opacity: 1, y: 0 }}
              whileHover={{ y: -2 }}
              transition={{ duration: 0.18 }}
              className="surface p-5 text-left hover:border-indigo-200 hover:shadow-md transition-all"
            >
              <div className="flex items-start justify-between gap-2">
                {renamingId === r.id ? (
                  <input
                    autoFocus
                    className="field h-8 text-sm font-semibold"
                    value={renameDraft}
                    onChange={(e) => setRenameDraft(e.target.value)}
                    onClick={(e) => e.stopPropagation()}
                    onBlur={() => {
                      renameTailored(r.id, renameDraft.trim() || r.label);
                      setRenamingId(null);
                    }}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") {
                        renameTailored(r.id, renameDraft.trim() || r.label);
                        setRenamingId(null);
                      }
                      if (e.key === "Escape") setRenamingId(null);
                    }}
                  />
                ) : (
                  <h3 className="font-semibold text-slate-900 leading-snug">
                    {r.label || "Untitled"}
                  </h3>
                )}
                <div className="flex gap-1">
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      setRenamingId(r.id);
                      setRenameDraft(r.label);
                    }}
                    className="p-1.5 rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-700"
                    title="Rename"
                  >
                    <Pencil className="h-3.5 w-3.5" />
                  </button>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      if (confirm("Delete this saved resume?")) {
                        removeTailored(r.id);
                      }
                    }}
                    className="p-1.5 rounded-lg text-slate-400 hover:bg-rose-50 hover:text-rose-600"
                    title="Delete"
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                  </button>
                </div>
              </div>
              <div className="mt-3 space-y-1.5 text-xs text-slate-500">
                {r.company && (
                  <div className="flex items-center gap-1.5">
                    <Building2 className="h-3 w-3" />
                    <span>{r.company}</span>
                  </div>
                )}
                <div className="flex items-center gap-1.5">
                  <Calendar className="h-3 w-3" />
                  <span>{formatDateLong(r.createdAt)}</span>
                </div>
              </div>
              {r.notes && (
                <p className="mt-3 text-xs text-slate-600 line-clamp-2">
                  {r.notes}
                </p>
              )}
            </motion.button>
          ))}
        </div>
      )}

      <AnimatePresence>
        {open && (
          <PreviewModal
            resume={open}
            master={master}
            rules={rules}
            onClose={() => setOpenId(null)}
          />
        )}
      </AnimatePresence>
    </div>
  );
}

function PreviewModal({
  resume,
  master,
  rules,
  onClose,
}: {
  resume: TailoredResume;
  master: ReturnType<typeof useStore.getState>["master"];
  rules: ReturnType<typeof useStore.getState>["settings"]["rules"];
  onClose: () => void;
}) {
  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      onClick={onClose}
      className="fixed inset-0 z-50 bg-slate-950/40 backdrop-blur-sm flex items-center justify-center p-6 overflow-auto no-print"
    >
      <motion.div
        onClick={(e) => e.stopPropagation()}
        initial={{ opacity: 0, scale: 0.96, y: 8 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.97, y: 4 }}
        transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
        className="relative max-w-[9.2in]"
      >
        <div className="absolute -top-12 right-0 flex gap-2 no-print">
          <button onClick={() => window.print()} className="btn-secondary">
            <Printer className="h-4 w-4" />
            Print / PDF
          </button>
          <button onClick={onClose} className="btn-secondary">
            <X className="h-4 w-4" />
            Close
          </button>
        </div>
        <div className="surface overflow-hidden">
          <ResumeDocument
            master={master}
            tailored={resume}
            rules={rules}
          />
        </div>
      </motion.div>
    </motion.div>
  );
}
