import { useState } from "react";
import { Eye, EyeOff, Lock, Save, Sparkles, ListOrdered } from "lucide-react";
import { useStore } from "@/store/useStore";
import { PageHeader } from "@/components/PageHeader";
import { clamp } from "@/lib/utils";

const MODELS = [
  { id: "claude-opus-4-7", label: "Opus 4.7 — best quality" },
  { id: "claude-sonnet-4-6", label: "Sonnet 4.6 — balanced (recommended)" },
  { id: "claude-haiku-4-5-20251001", label: "Haiku 4.5 — fastest" },
];

export default function SettingsPage() {
  const settings = useStore((s) => s.settings);
  const setSettings = useStore((s) => s.setSettings);

  const [draftKey, setDraftKey] = useState(settings.apiKey);
  const [showKey, setShowKey] = useState(false);
  const [savedFlash, setSavedFlash] = useState(false);

  const saveKey = () => {
    setSettings({ apiKey: draftKey.trim() });
    setSavedFlash(true);
    setTimeout(() => setSavedFlash(false), 1600);
  };

  return (
    <div className="px-8 py-10 max-w-3xl mx-auto">
      <PageHeader
        eyebrow="Settings"
        title="Configure once, tailor forever"
        description="Your API key and formatting rules. Stored only in this browser."
      />

      <div className="space-y-8">
        <section className="surface p-6">
          <div className="flex items-center gap-2 mb-1">
            <Lock className="h-4 w-4 text-indigo-500" />
            <h2 className="font-semibold text-slate-900">
              Anthropic API key
            </h2>
          </div>
          <p className="text-sm text-slate-500 mb-4">
            Get one at{" "}
            <a
              href="https://console.anthropic.com/"
              target="_blank"
              rel="noreferrer"
              className="text-indigo-600 hover:underline"
            >
              console.anthropic.com
            </a>
            . Stored locally — never sent anywhere except directly to Anthropic.
          </p>
          <div className="flex gap-2">
            <div className="relative flex-1">
              <input
                className="field pr-10 font-mono text-xs"
                type={showKey ? "text" : "password"}
                value={draftKey}
                onChange={(e) => setDraftKey(e.target.value)}
                placeholder="sk-ant-…"
              />
              <button
                onClick={() => setShowKey((v) => !v)}
                className="absolute inset-y-0 right-0 px-3 text-slate-400 hover:text-slate-700"
                title={showKey ? "Hide" : "Show"}
              >
                {showKey ? (
                  <EyeOff className="h-4 w-4" />
                ) : (
                  <Eye className="h-4 w-4" />
                )}
              </button>
            </div>
            <button onClick={saveKey} className="btn-primary">
              <Save className="h-4 w-4" />
              {savedFlash ? "Saved" : "Save"}
            </button>
          </div>

          <div className="mt-5">
            <p className="label mb-1.5">Model</p>
            <select
              className="field"
              value={settings.model}
              onChange={(e) => setSettings({ model: e.target.value })}
            >
              {MODELS.map((m) => (
                <option key={m.id} value={m.id}>
                  {m.label}
                </option>
              ))}
            </select>
          </div>
        </section>

        <section className="surface p-6">
          <div className="flex items-center gap-2 mb-1">
            <ListOrdered className="h-4 w-4 text-indigo-500" />
            <h2 className="font-semibold text-slate-900">Format rules</h2>
          </div>
          <p className="text-sm text-slate-500 mb-4">
            Hard limits enforced on every tailored resume.
          </p>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <RuleRow
              label="Max bullets per role"
              value={settings.rules.maxBulletsPerRole}
              min={2}
              max={10}
              onChange={(v) =>
                setSettings({
                  rules: { ...settings.rules, maxBulletsPerRole: v },
                })
              }
            />
            <RuleRow
              label="Max characters per bullet"
              value={settings.rules.maxBulletChars}
              min={80}
              max={250}
              onChange={(v) =>
                setSettings({
                  rules: { ...settings.rules, maxBulletChars: v },
                })
              }
            />
            <RuleRow
              label="Max skills shown"
              value={settings.rules.maxSkills}
              min={4}
              max={30}
              onChange={(v) =>
                setSettings({
                  rules: { ...settings.rules, maxSkills: v },
                })
              }
            />
            <RuleRow
              label="Summary sentences"
              value={settings.rules.summarySentences}
              min={1}
              max={5}
              onChange={(v) =>
                setSettings({
                  rules: { ...settings.rules, summarySentences: v },
                })
              }
            />
          </div>
        </section>

        <section className="surface p-6">
          <div className="flex items-center gap-2 mb-1">
            <Sparkles className="h-4 w-4 text-indigo-500" />
            <h2 className="font-semibold text-slate-900">How tailoring works</h2>
          </div>
          <ul className="mt-2 space-y-2 text-sm text-slate-600">
            <li className="flex gap-2">
              <span className="text-indigo-500">•</span>
              The model receives your master profile and the job description.
            </li>
            <li className="flex gap-2">
              <span className="text-indigo-500">•</span>
              It picks the most relevant existing bullets per role and tweaks
              wording — never meaning, never new facts.
            </li>
            <li className="flex gap-2">
              <span className="text-indigo-500">•</span>
              Format is fixed: identical layout every time, page-print ready.
            </li>
            <li className="flex gap-2">
              <span className="text-indigo-500">•</span>
              Nothing leaves your browser except direct calls to the Anthropic
              API.
            </li>
          </ul>
        </section>
      </div>
    </div>
  );
}

function RuleRow({
  label,
  value,
  min,
  max,
  onChange,
}: {
  label: string;
  value: number;
  min: number;
  max: number;
  onChange: (v: number) => void;
}) {
  return (
    <label className="block">
      <span className="label">{label}</span>
      <div className="mt-1.5 flex items-center gap-3">
        <input
          type="range"
          className="flex-1 accent-indigo-600"
          min={min}
          max={max}
          value={value}
          onChange={(e) => onChange(Number(e.target.value))}
        />
        <input
          type="number"
          className="field w-20"
          min={min}
          max={max}
          value={value}
          onChange={(e) =>
            onChange(clamp(Number(e.target.value) || min, min, max))
          }
        />
      </div>
    </label>
  );
}
