import { useMemo, useState } from "react";
import { motion } from "framer-motion";
import { Bookmark, Check, Copy, Printer, Sparkles, Wand2 } from "lucide-react";
import { Link } from "react-router-dom";
import { useStore } from "@/store/useStore";
import { PageHeader } from "@/components/PageHeader";
import { ResumeDocument } from "@/components/ResumeDocument";
import { TailorComposer } from "@/components/TailorComposer";
import type { TailoredResume } from "@/types";
import { cn } from "@/lib/utils";

export default function TailorPage() {
  const master = useStore((s) => s.master);
  const settings = useStore((s) => s.settings);
  const saveTailored = useStore((s) => s.saveTailored);

  const [result, setResult] = useState<TailoredResume | null>(null);
  const [loading, setLoading] = useState(false);
  const [saved, setSaved] = useState(false);
  const [view, setView] = useState<"preview" | "diff">("preview");

  const ready = master.experiences.length > 0;
  const hasKey = settings.apiKey.trim().length > 0;

  const totalChanged = useMemo(() => {
    if (!result) return 0;
    return result.experiences.reduce(
      (sum, e) => sum + e.bullets.filter((b) => b.changed).length,
      0
    );
  }, [result]);

  const handleResult = (r: TailoredResume) => {
    setResult(r);
    setSaved(false);
  };

  const composerDisabledReason = !ready
    ? "Add at least one role with bullets in your master profile first."
    : !hasKey
      ? "Add your Anthropic API key in Settings to enable tailoring."
      : undefined;

  const save = () => {
    if (!result) return;
    saveTailored(result);
    setSaved(true);
  };

  const copyText = async () => {
    if (!result) return;
    const text = renderAsPlainText(result, master);
    await navigator.clipboard.writeText(text);
  };

  return (
    <div className="px-8 py-10 max-w-[1500px] mx-auto">
      <PageHeader
        eyebrow="Tailor"
        title="One job, one tailored resume"
        description="Paste the job description. We tweak wording — never meaning — pick the most relevant bullets, and write a focused summary."
        actions={
          result && !loading ? (
            <>
              <button onClick={() => window.print()} className="btn-secondary">
                <Printer className="h-4 w-4" />
                Print / PDF
              </button>
              <button onClick={copyText} className="btn-secondary">
                <Copy className="h-4 w-4" />
                Copy text
              </button>
              <button
                onClick={save}
                className={cn("btn-primary", saved && "opacity-80")}
                disabled={saved}
              >
                {saved ? (
                  <>
                    <Check className="h-4 w-4" /> Saved
                  </>
                ) : (
                  <>
                    <Bookmark className="h-4 w-4" /> Save to library
                  </>
                )}
              </button>
            </>
          ) : null
        }
      />

      <div className="grid grid-cols-1 lg:grid-cols-[480px_minmax(0,1fr)] gap-10 mt-2">
        <div className="space-y-5">
          <TailorComposer
            onResult={handleResult}
            onLoadingChange={setLoading}
            disabled={!ready || !hasKey}
            {...(composerDisabledReason
              ? { disabledReason: composerDisabledReason }
              : {})}
          />
          {(!ready || !hasKey) && (
            <p className="text-xs text-slate-500 px-1">
              {!ready ? (
                <>
                  Set up your{" "}
                  <Link to="/profile" className="underline font-medium">
                    master profile
                  </Link>{" "}
                  first.
                </>
              ) : (
                <>
                  Add your key in{" "}
                  <Link to="/settings" className="underline font-medium">
                    Settings
                  </Link>
                  .
                </>
              )}
            </p>
          )}

          {result && (
            <motion.div
              initial={{ opacity: 0, y: 6 }}
              animate={{ opacity: 1, y: 0 }}
              className="surface p-5 space-y-3"
            >
              <p className="label">What we changed</p>
              <div className="flex items-center gap-3 text-sm">
                <Stat
                  value={totalChanged}
                  label={totalChanged === 1 ? "tweak" : "tweaks"}
                />
                <Stat
                  value={result.experiences.reduce(
                    (s, e) => s + e.bullets.length,
                    0
                  )}
                  label="bullets selected"
                />
              </div>
              {result.notes && (
                <p className="text-sm text-slate-600 leading-relaxed">
                  <Sparkles className="inline h-3.5 w-3.5 text-indigo-500 mr-1" />
                  {result.notes}
                </p>
              )}
              <div className="flex items-center gap-2 pt-1">
                <ToggleButton
                  active={view === "preview"}
                  onClick={() => setView("preview")}
                >
                  Preview
                </ToggleButton>
                <ToggleButton
                  active={view === "diff"}
                  onClick={() => setView("diff")}
                >
                  Diff
                </ToggleButton>
              </div>
            </motion.div>
          )}
        </div>

        <div className="min-w-0">
          {!result && !loading && <Placeholder ready={ready && hasKey} />}
          {loading && <LoadingShimmer />}
          {result && view === "preview" && (
            <motion.div
              initial={{ opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              className="overflow-auto"
            >
              <div className="surface inline-block">
                <ResumeDocument
                  master={master}
                  tailored={result}
                  rules={settings.rules}
                />
              </div>
            </motion.div>
          )}
          {result && view === "diff" && (
            <DiffView master={master} result={result} />
          )}
        </div>
      </div>
    </div>
  );
}

function Stat({ value, label }: { value: number; label: string }) {
  return (
    <span className="inline-flex items-baseline gap-1">
      <span className="text-2xl font-semibold tabular-nums text-slate-900">
        {value}
      </span>
      <span className="text-xs text-slate-500">{label}</span>
    </span>
  );
}

function ToggleButton({
  active,
  onClick,
  children,
}: {
  active: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <button
      onClick={onClick}
      className={cn(
        "h-8 rounded-lg px-3 text-sm font-medium transition-colors",
        active
          ? "bg-slate-900 text-white"
          : "bg-slate-100 text-slate-600 hover:bg-slate-200"
      )}
    >
      {children}
    </button>
  );
}

function Placeholder({ ready }: { ready: boolean }) {
  return (
    <div className="surface p-12 flex flex-col items-center text-center min-h-[600px] justify-center">
      <div className="h-14 w-14 rounded-2xl bg-gradient-to-br from-indigo-500 to-violet-600 flex items-center justify-center mb-5 shadow-lg shadow-indigo-500/20">
        <Wand2 className="h-7 w-7 text-white" />
      </div>
      <h3 className="text-lg font-semibold text-slate-900">
        Your tailored resume will appear here
      </h3>
      <p className="text-sm text-slate-500 max-w-md mt-1.5">
        {ready
          ? "Paste a job description on the left and hit Tailor. The output uses a fixed format — same shape every time."
          : "Once your master profile and API key are set up, this is where your tailored resume will render."}
      </p>
    </div>
  );
}

function LoadingShimmer() {
  return (
    <div className="surface p-8 space-y-4 animate-pulse">
      <div className="h-8 w-1/2 bg-slate-200 rounded" />
      <div className="h-3 w-1/3 bg-slate-200 rounded" />
      <div className="h-px bg-slate-200 my-4" />
      <div className="space-y-2">
        <div className="h-3 w-full bg-slate-200 rounded" />
        <div className="h-3 w-5/6 bg-slate-200 rounded" />
        <div className="h-3 w-4/6 bg-slate-200 rounded" />
      </div>
      <div className="h-px bg-slate-200 my-4" />
      <div className="space-y-3">
        {[1, 2, 3].map((i) => (
          <div key={i}>
            <div className="h-4 w-2/5 bg-slate-200 rounded mb-2" />
            <div className="space-y-1.5">
              <div className="h-3 w-full bg-slate-200 rounded" />
              <div className="h-3 w-11/12 bg-slate-200 rounded" />
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function DiffView({
  master,
  result,
}: {
  master: ReturnType<typeof useStore.getState>["master"];
  result: TailoredResume;
}) {
  return (
    <div className="space-y-5">
      <div className="surface p-5">
        <p className="label mb-2">Summary — Tailored</p>
        <p className="text-sm text-slate-800 leading-relaxed">
          {result.summary}
        </p>
        {master.summary && (
          <>
            <p className="label mt-4 mb-2">Summary — Original</p>
            <p className="text-sm text-slate-500 leading-relaxed line-clamp-4">
              {master.summary}
            </p>
          </>
        )}
      </div>
      {result.experiences.map((te) => {
        const exp = master.experiences.find((e) => e.id === te.experienceId);
        if (!exp) return null;
        return (
          <div className="surface p-5" key={te.experienceId}>
            <h3 className="text-base font-semibold text-slate-900">
              {exp.role || "Role"}
              {exp.company ? (
                <span className="text-slate-500 font-normal">
                  {" "}
                  · {exp.company}
                </span>
              ) : null}
            </h3>
            <ul className="mt-3 space-y-3">
              {te.bullets.map((b) => (
                <li
                  key={b.originalId}
                  className={cn(
                    "rounded-xl border p-3",
                    b.changed
                      ? "border-indigo-200 bg-indigo-50/40"
                      : "border-slate-200 bg-white"
                  )}
                >
                  {b.changed ? (
                    <>
                      <div className="text-sm text-slate-900">{b.tweaked}</div>
                      <div className="mt-1 text-xs text-slate-500 line-through decoration-slate-300">
                        {b.original}
                      </div>
                      {b.rationale && (
                        <div className="mt-2 text-[11px] text-indigo-700/90 italic">
                          {b.rationale}
                        </div>
                      )}
                    </>
                  ) : (
                    <div className="text-sm text-slate-800">{b.tweaked}</div>
                  )}
                </li>
              ))}
            </ul>
          </div>
        );
      })}
    </div>
  );
}

function renderAsPlainText(
  result: TailoredResume,
  master: ReturnType<typeof useStore.getState>["master"]
): string {
  const lines: string[] = [];
  const c = master.contact;
  lines.push(c.fullName);
  if (c.headline) lines.push(c.headline);
  lines.push(
    [c.location, c.email, c.phone, c.linkUrl].filter(Boolean).join(" • ")
  );
  if (result.summary) {
    lines.push("", "SUMMARY", result.summary);
  }
  if (result.experiences.length) {
    lines.push("", "EXPERIENCE");
    for (const te of result.experiences) {
      const exp = master.experiences.find((e) => e.id === te.experienceId);
      if (!exp) continue;
      lines.push(
        "",
        `${exp.role}${exp.company ? " · " + exp.company : ""}${
          exp.location ? " · " + exp.location : ""
        }`
      );
      for (const b of te.bullets) {
        lines.push(`• ${b.tweaked}`);
      }
    }
  }
  if (result.skills?.length) {
    lines.push("", "SKILLS", result.skills.join(" · "));
  }
  if (master.education.length) {
    lines.push("", "EDUCATION");
    for (const ed of master.education) {
      lines.push(`${ed.degree}${ed.school ? " · " + ed.school : ""}`);
      if (ed.detail) lines.push(ed.detail);
    }
  }
  return lines.join("\n");
}
